const std = @import("std");
const zmath = @import("zmath");

extern fn zmath_core_log10p1h_bits(bits: u16) callconv(.c) u16;
extern fn zmath_core_log2p1h_bits(bits: u16) callconv(.c) u16;

pub fn main(init: std.process.Init) !void {
    var half_inputs = [_]f16{ @bitCast(@as(u16, 0x3e00)), @bitCast(@as(u16, 0x8071)) };
    var fused_inputs = [_]f32{ @bitCast(@as(u32, 0x3f800800)), @bitCast(@as(u32, 0x3f800800)), @bitCast(@as(u32, 0x0d800000)) };
    std.mem.doNotOptimizeAway(&half_inputs);
    std.mem.doNotOptimizeAway(&fused_inputs);
    const half = zmath.scalar.atan2h(half_inputs[0], half_inputs[1]);
    const half_bits: u16 = @bitCast(half.value);
    const fused_bits: u32 = @bitCast(zmath.scalar.fmaf(fused_inputs[0], fused_inputs[1], fused_inputs[2]));
    if (!half.resolved or half_bits != 0x3e49 or fused_bits != 0x3f801001) return error.IncorrectMath;
    var buffer: [256]u8 = undefined;
    var stdout: std.Io.File.Writer = .init(.stdout(), init.io, &buffer);
    try stdout.interface.print("half C ABI atan2=0x{x}, one-round fmaf=0x{x}\n", .{ half_bits, fused_bits });
    const log10_inf = zmath_core_log10p1h_bits(0x7c00);
    const log2_inf = zmath_core_log2p1h_bits(0x7c00);
    try stdout.interface.print("half C ABI +Inf logs=0x{x}/0x{x}\n", .{ log10_inf, log2_inf });
    try stdout.interface.flush();
    if (log10_inf != 0x7c00 or log2_inf != 0x7c00) return error.IncorrectLogInfinity;
    try stdout.interface.flush();
}

